/// <summary>
/// This is a framework class. Customizing this class may cause problems with future upgrades to the software.
/// </summary>
class AVACAMDataImportClear extends RunBaseBatch
{
    QueryRun     queryRun;
    #define.CurrentVersion(1)

}

Method.Source:
/// <summary>
///    Indicates whether the class is shown in the list of <c>Journal</c> types.
/// </summary>
/// <returns>
///    true if the class is shown in the list of <c>Journal</c> types; otherwise, false.
/// </returns>
/// <remarks>
///    A class that can be used in a batch journal is a class where the same parameters can be used
///    repeatedly. The dialog box can be shown and the parameters can be changed, but parameters of some
///    classes might build on data that is only valid for a short time. Running a class two times with the
///    same parameters is not always possible. If the <c>RunBaseBatch.canGoBatch</c> method is false, this
///    method will not have any effect.
/// </remarks>
public boolean canGoBatchJournal()
{
    return true;
}

/// <summary>
///    Returns a class that contains the methods that are described by the <c>RunBaseDialogable</c>
///    interface.
/// </summary>
/// <returns>
///    A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
///    A dialog box can be either built by using the <c>Dialog</c> class or by using a class that is
///    created in the Application Object Tree (AOT).
/// </remarks>
public Object dialog()
{
    DialogRunbase       dialog = super();
    return dialog;
}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
public void run()
{
    #OCCRetryCount
    if (! this.validate())
    {
        //TODO: Missing error message
        throw error('');
    }

    try
    {
       // ttsbegin;
        CAMDataImportedStatisticalMeasure   CAMDataImportedStatisticalMeasure;

        while(queryRun.next())
        {
            CAMDataImportedStatisticalMeasure = queryRun.get(tableNum(CAMDataImportedStatisticalMeasure));
            ttsbegin;
            CAMDataImportedStatisticalMeasure.selectForUpdate(true);
            CAMDataImportedStatisticalMeasure.delete();
            ttscommit;
        }

       // ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

public boolean unpack(container _packedClass)
{
    boolean     ret         = false;
    int         version     = RunBase::getVersion(_packedClass);
    container   packedQuery = conNull();

    switch (version)
    {
        case #CurrentVersion:
            [version, packedQuery] = _packedClass;

            if (SysQuery::isPackedOk(packedQuery))
            {
                QueryRun   = new QueryRun(packedQuery);
                ret         = true;
            }
            break;

        default:
            ret = false;
    }
    return ret;
}

public boolean validate(Object _calledFrom = null)
{
    if (false)
    {
        //TODO: Missing error message
        return checkFailed('');
    }

    return true;
}

static AVACAMDataImportClear construct()
{
    return new AVACAMDataImportClear();
}

/// <summary>
/// Here goes a description of the class
/// </summary>
/// <returns>ClassDescription</returns>
static ClassDescription description()
{
    return 'CAM Data import clear';
}

static void main(Args args)
{
    AVACAMDataImportClear    AVACAMDataImportClear;
    ;
    AVACAMDataImportClear = AVACAMDataImportClear::construct();

    if (AVACAMDataImportClear.prompt())
    {
        AVACAMDataImportClear.runOperation();
    }
}

/// <summary>
/// showQueryValues method
/// </summary>
/// <returns>boolean</returns>
public boolean showQueryValues()
{
    return true;
}

/// <summary>
/// queryRun method
/// </summary>
/// <returns>QueryRun</returns>
public QueryRun queryRun()
{
    return queryRun;
}

/// <summary>
/// initQueryRun method
/// </summary>
public void initQueryRun()
{
    Query                               query = new Query();

    query.addDataSource(tableNum(CAMDataImportedStatisticalMeasure));

    queryRun = new QueryRun(query);
    queryRun.saveUserSetup(true);
}

/// <summary>
/// designed rom AVA
/// </summary>
public void initParmDefault()
{
    super();
    this.initQueryRun();
}
